def max_no_bad_days(sales):
  l, r = 0, 0
  cur_max = 0
  while r < len(sales):
    can_grow = sales[r] >= 10
    if can_grow:
      r += 1
      cur_max = max(cur_max, r - l)
    else:
      l = r + 1
      r = r + 1
  return cur_max

