class MaxNoBadDays {
  public int solve(int[] sales) {
    int l = 0, r = 0;
    int curMax = 0;
    while (r < sales.length) {
      boolean canGrow = sales[r] >= 10;
      if (canGrow) {
        r++;
        curMax = Math.max(curMax, r - l);
      } else {
        l = r + 1;
        r = r + 1;
      }
    }
    return curMax;
  }
}

